(function(){
'use strict';
function ar(){return document.documentElement.lang!=='en';}
function t(a,b){return ar()?a:b;}
function phaseCard(number,title,desc,href,cta,extra,status=t('متاح محليًا','AVAILABLE LOCALLY')){return '<article class="release-phase-card"><div class="release-phase-top"><span class="release-phase-number">'+number+'</span><span class="release-phase-status">'+status+'</span></div><h3>'+title+'</h3><p>'+desc+'</p><div class="release-phase-tags">'+extra.map(x=>'<span>'+x+'</span>').join('')+'</div><a href="'+href+'">'+cta+' <span aria-hidden="true">'+t('←','→')+'</span></a></article>';}
function suite(){return '<section id="miyar-release-home" class="release-suite" aria-labelledby="release-suite-title"><div id="lp-services" class="lp-wrap"><div class="release-suite-head"><div><span class="lp-eyebrow">'+t('خدمات معيار — اختر القرار الذي تحتاجه','MIYAR SERVICES — CHOOSE YOUR DECISION')+'</span><h2 id="release-suite-title">'+t('بعد تحديد الاحتياج والدور،<br><em>أكمل القرار داخل نفس المنصة.</em>','Once the need and role are clear,<br><em>continue the decision in the same platform.</em>')+'</h2></div><p>'+t('لا تحتاج رؤية كل الأدوات في البداية. بعد أن يحدد معيار الاحتياج والدور، تظهر أدوات تصميم الوظيفة وتخطيط العدد والتعويض والاعتماد عند الحاجة.','You do not need every tool up front. Once Miyar clarifies the need and role, job design, workforce planning, compensation and approval become available when needed.')+'</p></div><div class="release-phase-grid">'+
phaseCard('01',t('التطوير التنظيمي وتصميم الوظيفة','OD & Job Architecture'),t('حوّل الهدف والمسؤوليات إلى مسمى وغرض ووصف وظيفي وجدارات ومؤشرات أداء وعائلة ومسار مهني، ثم اربطها بـSSCO والتعليم والتقييم والاعتماد.','Turn strategy and responsibilities into title, purpose, JD, competencies, KPIs, job family and career path, then connect them to SSCO, education, evaluation and approval.'),'#enterprise/create',t('افتح محرك OD','Open OD Engine'),[t('وصف وظيفي كامل','Full JD'),t('SSCO + التعليم','SSCO + Education'),t('الدرجة والمسار','Grade + Career Path')])+
phaseCard('02',t('تخطيط القوى العاملة','Manpower Planning'),t('حوّل الطلب المتوقع والطاقة الإنتاجية والعرض الحالي إلى Required FTE وForecast Supply وفجوة واضحة عبر سيناريوهات محافظة وأساسية وعالية.','Convert demand, productivity and current supply into Required FTE, Forecast Supply and a transparent gap across lower, base and higher-demand scenarios.'),'#enterprise/manpower',t('افتح تخطيط القوى العاملة','Open Manpower Planning'),[t('3 سيناريوهات','3 scenarios'),t('فجوة FTE','FTE gap'),t('Gap → OD','Gap → OD')])+
phaseCard('03',t('التعويضات','Compensation'),t('اربط الدرجة بنطاق الراتب المعتمد لدى الجهة، واحسب positioning وcompa-ratio والأثر السنوي دون اختلاق بيانات سوقية غير موثقة.','Connect the grade to the organization-approved salary band and calculate positioning, compa-ratio and annual cost impact without inventing unsupported market pay data.'),'#enterprise/compensation',t('افتح التعويضات','Open Compensation'),[t('Salary Bands','Salary Bands'),t('Compa-ratio','Compa-ratio'),t('أثر التكلفة','Cost impact')])+
phaseCard('04',t('تحليل متطلبات المهارات','Role skill requirements'),t('استخرج المهارات مع العبارة الدالة ومصدرها. هذا يحدد متطلبات العمل؛ قياس إتقان الموظف يحتاج تقييمًا مستقلًا.','Extract skills with their text evidence and provenance. This identifies role requirements; employee proficiency needs a separate assessment.'),'#enterprise/intelligence',t('افتح تحليل المهارات','Open skill analysis'),[t('قاموس ثنائي اللغة','Bilingual dictionary'),t('دليل النص','Text evidence')])+
phaseCard('05',t('التقييم الوظيفي والدرجة','Job evaluation & grade'),t('قيّم حجم الوظيفة بأدلة لكل عامل، ثم اربط النقاط بهيكل درجات الجهة. المثال المحلي توضيحي ويحتاج إطارًا معتمدًا قبل القرار.','Evaluate job size with evidence for each factor, then resolve points to organization grades. Local examples are illustrative and need an approved framework before a decision.'),'#enterprise/grading',t('افتح تقييم الوظائف','Open job evaluation'),[t('عوامل وأدلة','Factors & evidence'),t('درجة ← تعويض','Grade → pay')])+
phaseCard('06',t('الاعتماد وحزمة المنصب','Approval & position package'),t('احفظ مسودة ومعاينة محليًا وصدّر JSON. PDF يحتاج اتصال الخادم؛ الاعتمادات وDOCX/XLSX والإيصالات تحتاج حساب المؤسسة وصلاحياتها.','Save and preview drafts locally, and export JSON. PDF requires the server; approvals, DOCX/XLSX and receipts require an organization account and permissions.'),'#enterprise/workspace',t('افتح طلبات المناصب','Open position requests'),[t('إصدارات','Revisions'),t('PDF / DOCX / XLSX','PDF / DOCX / XLSX')],t('اعتماد المؤسسة بعد الدخول','ORGANIZATION APPROVAL AFTER SIGN-IN'))+
'</div><div class="release-foundation"><div><strong>'+t('تهيئة مؤسسية لمرة واحدة','ONE-TIME INSTITUTION SETUP')+'</strong><p>'+t('حمّل الهيكل التنظيمي وهيكل الدرجات المعتمد مرة واحدة، ليستخدمهما محرك OD في كل طلب جديد.','Configure the approved organization structure and grade architecture once, then reuse them across OD decisions.')+'</p></div><div><strong>'+t('مرجع سعودي بإصدار موثق','VERSIONED SAUDI REFERENCE LAYER')+'</strong><p>'+t('يحافظ معيار على 5,041 سجل مهنة من إصدار يناير 2019 المرفق بالمشروع و599 تخصصًا تعليميًا من إصدار 2020، مع إظهار الإصدار وحدود الصلاحية. للقرارات الحالية يجب التحقق من SSCO المنشور حاليًا لدى الهيئة العامة للإحصاء.','Miyar preserves 5,041 occupation records from the supplied January 2019 edition and 599 education specializations from the supplied 2020 edition, with edition and applicability limits kept visible. Current decisions must be verified against the SSCO currently published by GASTAT.')+'</p></div><div><strong>'+t('حوكمة القرار','DECISION GOVERNANCE')+'</strong><p>'+t('إصدارات، صلاحيات، مراجعات مستقلة، أدلة تقييم، ومخرجات PDF/DOCX/XLSX مرتبطة بالنسخة التي تمت مراجعتها.','Revisions, permissions, independent reviews, evaluation evidence, and PDF/DOCX/XLSX outputs tied to the reviewed revision.')+'</p></div></div><nav class="release-service-links" aria-label="'+t('خدمات ومراجع إضافية','Additional services and references')+'"><a href="#enterprise/reference">'+t('دليل المهن والتعليم','Occupation & education directory')+'</a><a href="#enterprise/bulk">'+t('فحص الهيكل','Structure checks')+'</a><a href="#enterprise/tour">'+t('دليل الاستخدام','User guide')+'</a><a href="./trust.html#status">'+t('الحالة الحالية للخدمات وAI','Current service & AI status')+'</a></nav><div class="release-cta"><div><span>'+t('المسار الكامل','END-TO-END FLOW')+'</span><strong>'+t('الاستراتيجية ← التطوير التنظيمي ← التقييم ← القوى العاملة ← التعويضات ← الاعتماد','Strategy → OD → Evaluation → Manpower → Compensation → Approval')+'</strong></div><a class="lp-button lp-primary" href="#enterprise/create">'+t('ابدأ بقرار عمل حقيقي','Start with a real business need')+'</a></div></div></section>';}
function apply(){
 const home=document.getElementById('view-home');if(!home||home.hidden||!home.querySelector('.lp-hero'))return false;
 const copy=home.querySelector('.lp-hero-copy');
 if(copy){
  if(!copy.querySelector('[data-full-site-ai]')){
   const entry=document.createElement('div');entry.className='release-ai-entry';
   entry.innerHTML='<a class="lp-button lp-primary" href="#demo" data-full-site-ai>'+t('جرّب AI — تجربة الخبراء المحدودة','Try AI — time-limited expert trial')+'</a><p>'+t('مسار AI يحتاج موافقة إرسال البيانات، ويخضع لنافذة التجربة وحدها اليومي. الترشيح بالقواعد وتصميم الوظيفة والحسابات المحلية متاحة دون إرسال النص.','AI requires data-processing consent and is subject to the trial window and daily limit. Rule-based recommendations, job design and local calculations work without sending your text.')+'</p>';
   entry.querySelector('a').addEventListener('click',()=>{try{sessionStorage.setItem('miyar-open-ai','1');}catch{}});
   copy.append(entry);
  }
  const eyebrow=copy.querySelector('.lp-eyebrow');if(eyebrow)eyebrow.textContent=t('لمديري الموارد البشرية والتطوير التنظيمي والمالية','FOR HR, ORGANIZATION DEVELOPMENT & FINANCE');
 }
 home.querySelectorAll('.lp-nav [data-release-nav]').forEach(x=>x.remove());
 if(!home.querySelector('#miyar-release-home')){const proof=home.querySelector('.lp-proof');if(proof)proof.insertAdjacentHTML('afterend',suite());else home.querySelector('main')?.insertAdjacentHTML('beforeend',suite());}
 return true;
}
let scheduled=false;function schedule(){if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;apply();},0);}const observer=new MutationObserver(schedule);observer.observe(document.documentElement,{subtree:true,childList:true});window.addEventListener('hashchange',schedule);window.addEventListener('miyar:navigate',schedule);document.addEventListener('DOMContentLoaded',schedule);schedule();window.MiyarReleaseHome={apply};
})();